import{_ as a,o as t,c as n,a8 as e}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"104 Prompt Engineering 系统指南","description":"","frontmatter":{"title":"104 Prompt Engineering 系统指南"},"headers":[],"relativePath":"104-prompt-engineering.md","filePath":"104-prompt-engineering.md","lastUpdated":1793706365000}'),p={name:"104-prompt-engineering.md"};function i(d,s,o,l,r,h){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="第一百零四部分-·-prompt-engineering-系统指南" tabindex="-1">第一百零四部分 · Prompt Engineering 系统指南 <a class="header-anchor" href="#第一百零四部分-·-prompt-engineering-系统指南" aria-label="Permalink to &quot;第一百零四部分 · Prompt Engineering 系统指南&quot;">​</a></h1><blockquote><p>🧭 <a href="./README">返回总目录</a>｜上一篇：<a href="./103-langchain-dify">第一百零三部分 · LangChain 与 Dify 工具链</a>｜关联章节：<a href="./33-zod">第三十三部分 · Zod Schema 校验</a> · <a href="./14-frontend-ai">第十四部分 · 前端 AI 应用</a> · <a href="./103-langchain-dify">第一百零三部分 · LangChain 与 Dify</a></p></blockquote><h2 id="本部分内容" tabindex="-1">本部分内容 <a class="header-anchor" href="#本部分内容" aria-label="Permalink to &quot;本部分内容&quot;">​</a></h2><p>提示词（Prompt）是连接人类意图和 LLM 能力的唯一接口——<strong>它不是一门神秘艺术，而是一套可系统化的工程方法</strong>。好的提示词设计遵循明确的结构、可度量的效果、可版本化的迭代。本部分从「提示词应该长什么样」讲起，覆盖角色/约束/输出契约三件套、Few-shot 与 CoT 的正确打开方式、结构化输出的工程化实现（JSON Schema + 校验重试，衔接 33 册 Zod）、以及提示词版本管理与评测驱动迭代的完整闭环。</p><hr><h2 id="_104-1-提示词的本质与设计范式" tabindex="-1">104.1 提示词的本质与设计范式 <a class="header-anchor" href="#_104-1-提示词的本质与设计范式" aria-label="Permalink to &quot;104.1 提示词的本质与设计范式&quot;">​</a></h2><h3 id="提示词是什么" tabindex="-1">提示词是什么 <a class="header-anchor" href="#提示词是什么" aria-label="Permalink to &quot;提示词是什么&quot;">​</a></h3><p>提示词是给 LLM 设定「角色 + 目标 + 约束 + 输出格式」的组合指令。LLM 本质上是一个条件概率模型——它预测的是「给定前文，下一个 token 是什么」。提示词就是那个「前文」的关键部分。</p><p><strong>好提示词的四要素</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>角色（Who） + 任务（What） + 约束（How） + 输出契约（Output）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>要素</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td>角色</td><td>锚定 LLM 的知识边界和语气风格</td><td>&quot;你是一名资深前端架构师，熟悉 Vue 3 / React 19 / TypeScript&quot;</td></tr><tr><td>任务</td><td>明确要做什么</td><td>&quot;帮我审查以下组件设计，指出潜在的性能问题&quot;</td></tr><tr><td>约束</td><td>限定怎么做</td><td>&quot;不要超过 3 条建议，每条必须有代码示例&quot;</td></tr><tr><td>输出契约</td><td>规定输出格式</td><td>&quot;输出 JSON，包含 code / issue / suggestion 三个字段&quot;</td></tr></tbody></table><h3 id="常见反模式" tabindex="-1">常见反模式 <a class="header-anchor" href="#常见反模式" aria-label="Permalink to &quot;常见反模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>反模式</th><th>问题</th><th>正解</th></tr></thead><tbody><tr><td>「你是 AI 助手」</td><td>太泛，没有角色锚定</td><td>具体到领域和职责：「你是专门做企业后台的前端架构师」</td></tr><tr><td>大段自然语言描述</td><td>LLM 可能漏看约束</td><td>结构化分段：角色段 + 任务段 + 约束段 + 输出段</td></tr><tr><td>没输出格式</td><td>输出不稳定，前端解析困难</td><td>明确指定：JSON Schema / Markdown 模板 / 分隔符</td></tr><tr><td>一次性塞全部需求</td><td>LLM 注意力稀释</td><td>拆分多轮对话，每轮聚焦一个子任务</td></tr></tbody></table><hr><h2 id="_104-2-系统提示词设计-角色-约束-输出契约" tabindex="-1">104.2 系统提示词设计：角色/约束/输出契约 <a class="header-anchor" href="#_104-2-系统提示词设计-角色-约束-输出契约" aria-label="Permalink to &quot;104.2 系统提示词设计：角色/约束/输出契约&quot;">​</a></h2><p>系统提示词（System Prompt）是每轮对话都带的「人设」——LLM 在整个会话中都会遵循它。好的系统提示词遵循固定模板：</p><h3 id="模板结构" tabindex="-1">模板结构 <a class="header-anchor" href="#模板结构" aria-label="Permalink to &quot;模板结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Role（角色）</span></span>
<span class="line"><span>你是 [具体身份]，专长 [领域]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Capability（能力边界）</span></span>
<span class="line"><span>- 能做 A / B / C</span></span>
<span class="line"><span>- 不能做 X / Y / Z（遇到 XX 时，应该 YY）</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Constraints（约束）</span></span>
<span class="line"><span>1. 所有输出必须 [遵循规范]</span></span>
<span class="line"><span>2. 回答风格 [简洁/详细/正式/口语]</span></span>
<span class="line"><span>3. 不确定时说 &quot;我不确定&quot;，不编造</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Output Format（输出格式）</span></span>
<span class="line"><span>每次回答遵循：</span></span>
<span class="line"><span>## 问题理解 / ## 分析 / ## 建议</span></span></code></pre></div><h3 id="反例-vs-正例" tabindex="-1">反例 vs 正例 <a class="header-anchor" href="#反例-vs-正例" aria-label="Permalink to &quot;反例 vs 正例&quot;">​</a></h3><p><strong>反例</strong>（生产环境 80% 的系统提示词是这种水平）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个 AI 助手，帮用户解答前端问题。</span></span></code></pre></div><p>问题：角色模糊、没说能力边界、没输出格式、没约束。</p><p><strong>正例</strong>（企业级系统提示词）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Role</span></span>
<span class="line"><span>你是「Frontend Architect Copilot」，一名 10 年前端架构师。</span></span>
<span class="line"><span>你擅长：组件库设计、性能优化、微前端架构、DevOps 工程化。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Capability</span></span>
<span class="line"><span>- 能审查代码、设计组件 API、制定技术规范</span></span>
<span class="line"><span>- 不能运行代码、不能访问外部 API、不能获取实时数据</span></span>
<span class="line"><span>- 遇到不确定的 API 行为时，会说明「我需要验证」而不是编造</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Constraints</span></span>
<span class="line"><span>1. 建议必须有代码示例，不要空泛描述</span></span>
<span class="line"><span>2. 优先考虑可维护性 &gt; 性能 &gt; 炫技</span></span>
<span class="line"><span>3. 单个代码块不超过 30 行，超过先给思路</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Output Format</span></span>
<span class="line"><span>- 🔍 **问题**：一句话概括核心问题</span></span>
<span class="line"><span>- 💡 **根因**：为什么会出现</span></span>
<span class="line"><span>- ✅ **建议**：具体修复方案（含代码示例）</span></span></code></pre></div><h3 id="完整代码示例-提示词模板引擎" tabindex="-1">完整代码示例：提示词模板引擎 <a class="header-anchor" href="#完整代码示例-提示词模板引擎" aria-label="Permalink to &quot;完整代码示例：提示词模板引擎&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 文件: examples/104-01-prompt-template-engine.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 系统提示词模板引擎：角色 + 约束 + 输出契约三段式构建</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 支持变量插值、Few-shot 注入、版本标记</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// （完整实现见 examples/104-01）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 核心类 PromptTemplateEngine 接收 config → build() 生成系统提示词</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// buildUserMessage(template, vars) 支持 {{var}} 插值</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// examples 数组自动注入为 Few-shot 示例</span></span></code></pre></div><hr><h2 id="_104-3-结构化输出-json-schema-校验重试" tabindex="-1">104.3 结构化输出：JSON Schema + 校验重试 <a class="header-anchor" href="#_104-3-结构化输出-json-schema-校验重试" aria-label="Permalink to &quot;104.3 结构化输出：JSON Schema + 校验重试&quot;">​</a></h2><p>让 LLM 输出结构化 JSON 是 AI 应用工程化的核心需求——前端可以直接解析、存储、渲染。但 LLM 输出 JSON 时经常犯错（字段名不对、类型不对、枚举值不对），所以<strong>必须在校验失败时自动重试</strong>。</p><h3 id="为什么-llm-输出-json-会错" tabindex="-1">为什么 LLM 输出 JSON 会错 <a class="header-anchor" href="#为什么-llm-输出-json-会错" aria-label="Permalink to &quot;为什么 LLM 输出 JSON 会错&quot;">​</a></h3><p>LLM 没有「schema 合规」的硬约束——它只预测下一个 token。即使你在提示词里写了 &quot;输出必须是 JSON&quot;，它也可能：</p><ul><li>字段名拼写错误（<code>scores</code> vs <code>score</code>）</li><li>类型错误（<code>&quot;score&quot;: &quot;85&quot;</code> vs <code>&quot;score&quot;: 85</code>）</li><li>枚举值超范围（<code>severity: &quot;critical&quot;</code> 而 schema 只允许 <code>&quot;high|medium|low&quot;</code>）</li><li>输出前加解释文字，不是纯 JSON</li></ul><h3 id="校验重试循环" tabindex="-1">校验重试循环 <a class="header-anchor" href="#校验重试循环" aria-label="Permalink to &quot;校验重试循环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for attempt in 1..maxRetries:</span></span>
<span class="line"><span>  1. LLM 输出 → JSON.parse（捕获格式错误）</span></span>
<span class="line"><span>  2. parse 成功 → Schema 校验（捕获字段/类型错误）</span></span>
<span class="line"><span>  3. 校验成功 → 返回</span></span>
<span class="line"><span>  4. 校验失败 → 把错误信息喂回 LLM → 继续循环</span></span></code></pre></div><h3 id="完整代码示例-结构化输出提取器" tabindex="-1">完整代码示例：结构化输出提取器 <a class="header-anchor" href="#完整代码示例-结构化输出提取器" aria-label="Permalink to &quot;完整代码示例：结构化输出提取器&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 文件: examples/104-02-structured-output-retry.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 结构化输出：LLM → JSON.parse → Schema 校验 → 错误喂回 → 重试成功</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 目标：3 轮内把一条故意错误的 LLM 输出修正为符合 reviewSchema 的对象</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// （完整实现见 examples/104-02）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// FakeLLM 模拟 LLM：第 1 轮 issues 是字符串 + score 超范围；第 2 轮 severity 是 &quot;critical&quot; 不在枚举内；第 3 轮完全正确</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// extractStructured() 自动跑 3 轮，最终拿到合法的 ReviewOutput</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// reviewSchema 用简化版 Zod 做运行时校验</span></span></code></pre></div><hr><h2 id="_104-4-few-shot-与-chain-of-thought" tabindex="-1">104.4 Few-shot 与 Chain-of-Thought <a class="header-anchor" href="#_104-4-few-shot-与-chain-of-thought" aria-label="Permalink to &quot;104.4 Few-shot 与 Chain-of-Thought&quot;">​</a></h2><h3 id="few-shot-给模型看例子" tabindex="-1">Few-shot：给模型看例子 <a class="header-anchor" href="#few-shot-给模型看例子" aria-label="Permalink to &quot;Few-shot：给模型看例子&quot;">​</a></h3><p>Few-shot = 在提示词里给 LLM 看「输入-输出示例」，让它模仿格式。示例数量通常 3-5 个就够——太多会占用 token 预算，反而稀释效果。</p><p><strong>何时用 Few-shot</strong>：</p><ul><li>输出格式很特殊（比如「前端代码审查」格式：问题 → 根因 → 建议 → 代码）</li><li>风格很难用文字描述清楚（比如「模仿 Rust 编译器的错误提示风格」）</li><li>任务有隐含规则（比如「判断这句话是不是讽刺」，光说规则不如看 3 个例子）</li></ul><p><strong>反模式</strong>：不要把 Few-shot 示例和系统提示词正文混在一起——用 <code># Few-shot Examples</code> 单独标记，LLM 注意力会聚焦在明确分区内的内容上。</p><h3 id="chain-of-thought-cot-让模型说出思考过程" tabindex="-1">Chain-of-Thought（CoT）：让模型说出思考过程 <a class="header-anchor" href="#chain-of-thought-cot-让模型说出思考过程" aria-label="Permalink to &quot;Chain-of-Thought（CoT）：让模型说出思考过程&quot;">​</a></h3><p>CoT = 让 LLM 先一步步推理，再给最终答案。对复杂推理任务（数学、逻辑、多步决策）效果显著提升。</p><p><strong>两种写法</strong>：</p><ol><li><strong>显式触发</strong>：在提示词里写 &quot;请一步步思考，先分析每个条件，再给出结论&quot;</li><li><strong>隐式触发</strong>：在示例里展示思考过程，让模型模仿</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：小明有 5 个苹果，给了小红 3 个，又买了 2 个，现在有几个？</span></span>
<span class="line"><span>模型（显式 CoT）：</span></span>
<span class="line"><span>  1. 初始：5 个</span></span>
<span class="line"><span>  2. 给小红 3 个：5 - 3 = 2 个</span></span>
<span class="line"><span>  3. 又买了 2 个：2 + 2 = 4 个</span></span>
<span class="line"><span>  最终：4 个</span></span></code></pre></div><p><strong>注意</strong>：CoT 增加 token 消耗（大约 2-3 倍），简单任务（直接查表、简单分类）不要用。</p><h3 id="反-cot-直接要答案" tabindex="-1">反 CoT：直接要答案 <a class="header-anchor" href="#反-cot-直接要答案" aria-label="Permalink to &quot;反 CoT：直接要答案&quot;">​</a></h3><p>对结构化输出场景，应该明确拒绝思考过程——CoT 的中间推理文字会破坏 JSON 输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;帮我审查这段代码，先分析问题再给出 JSON 结果&quot;</span></span>
<span class="line"><span>✅ &quot;帮我审查这段代码，直接输出 JSON 对象，不要包含分析过程&quot;</span></span></code></pre></div><hr><h2 id="_104-5-提示词版本管理与评测驱动" tabindex="-1">104.5 提示词版本管理与评测驱动 <a class="header-anchor" href="#_104-5-提示词版本管理与评测驱动" aria-label="Permalink to &quot;104.5 提示词版本管理与评测驱动&quot;">​</a></h2><h3 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h3><p>提示词不是&quot;写好就不动&quot;——它会随着业务迭代而变化。建议用以下策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>做法</th></tr></thead><tbody><tr><td>版本化</td><td>每个提示词带版本号（<code>v1.2.0</code>），变更时递增</td></tr><tr><td>变更日志</td><td>记录每次变更的原因、内容、效果</td></tr><tr><td>A/B 测试</td><td>新提示词灰度放量，对比指标变化</td></tr><tr><td>Prompt 库</td><td>把提示词当成代码管理：Git 仓库 + PR 评审</td></tr></tbody></table><h3 id="评测驱动迭代" tabindex="-1">评测驱动迭代 <a class="header-anchor" href="#评测驱动迭代" aria-label="Permalink to &quot;评测驱动迭代&quot;">​</a></h3><p>提示词效果需要量化指标，不能靠&quot;我觉得更好了&quot;：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>度量方式</th></tr></thead><tbody><tr><td><strong>任务成功率</strong></td><td>输出是否通过 Schema 校验</td><td><code>合格输出数 / 总请求数</code></td></tr><tr><td><strong>人工评分</strong></td><td>专业人员对输出质量的评分（1-5 分）</td><td>抽样 + 双盲评估</td></tr><tr><td><strong>用户满意度</strong></td><td>最终用户的反馈（👍👎 按钮）</td><td>埋点统计</td></tr><tr><td><strong>Token 成本</strong></td><td>单次请求的 token 消耗</td><td><code>sum(prompt_tokens + completion_tokens) / 请求数</code></td></tr><tr><td><strong>延迟</strong></td><td>端到端响应时间</td><td>p50 / p95 / p99</td></tr></tbody></table><p><strong>评测集构建</strong>：</p><ol><li>找 50-200 条真实用户 query，覆盖正常 / 边界 / 异常场景</li><li>对每条 query 标注「期望输出」或「评分标准」</li><li>新提示词跑同一评测集，对比指标变化</li><li>如果「成功率 ↓」或「成本 ↑ 显著」，回滚或继续迭代</li></ol><hr><h2 id="_104-6-自测题" tabindex="-1">104.6 自测题 <a class="header-anchor" href="#_104-6-自测题" aria-label="Permalink to &quot;104.6 自测题&quot;">​</a></h2><details><summary><b>1. 好提示词的四要素是什么？分别起什么作用？【基础】</b></summary><p>角色（Who：锚定 LLM 知识边界和语气风格）、任务（What：明确要做什么）、约束（How：限定怎么做）、输出契约（Output：规定输出格式）。角色让 LLM 知道自己是谁、专长什么；任务让 LLM 知道目标；约束防止越界和走形；输出契约让前端能稳定解析。</p></details><details><summary><b>2. 为什么 LLM 输出 JSON 会经常错？结构化输出应该怎么实现？【基础】</b></summary><p>LLM 只预测下一个 token，没有 schema 合规的硬约束——即使提示词写了&quot;输出 JSON&quot;，也可能字段名拼错、类型不对、枚举值超范围、输出前加解释文字。实现方式：提示词里明确 JSON Schema → 拿 LLM 输出做 JSON.parse（捕获格式错误）→ 用 Zod/JSON Schema 做运行时校验（捕获字段/类型/枚举错误）→ 校验失败时把错误信息喂回 LLM 重试（通常 3 轮内收敛）→ 最终返回合法对象。</p></details><details><summary><b>3. Few-shot 和 CoT 分别是什么？何时用、何时不该用？【进阶】</b></summary><p>Few-shot = 给 LLM 看 3-5 个「输入-输出示例」让它模仿格式，用于输出格式特殊（代码审查格式）、风格难描述（模仿编译器报错）、任务有隐含规则（讽刺判断）的场景。示例数量 3-5 个够，太多浪费 token。</p><p>CoT（Chain-of-Thought）= 让 LLM 一步步推理再给答案，用于复杂推理（数学、多步决策、逻辑链）。<strong>不该用</strong>在：简单任务（查表、分类，直接要答案更快更省 token）、结构化输出场景（CoT 的推理文字会破坏 JSON，应该明确说&quot;不要分析过程，直接输出 JSON&quot;）。</p></details><details><summary><b>4. 系统提示词应该怎么设计？反例和正例分别是什么？【进阶】</b></summary><p><strong>反例</strong>：<code>&quot;你是一个 AI 助手，帮用户解答前端问题。&quot;</code> —— 角色模糊、没能力边界、没输出格式、没约束。</p><p><strong>正例</strong>（四段落模板）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Role  具体身份 + 专长领域</span></span>
<span class="line"><span># Capability  能做 / 不能做 + 遇到不能做的 fallback</span></span>
<span class="line"><span># Constraints  具体规则（必须有代码、单个代码块 ≤ 30 行等）</span></span>
<span class="line"><span># Output Format  明确的输出格式（JSON Schema 或 Markdown 模板）</span></span></code></pre></div><p>可选追加 # Version 和 # Few-shot Examples。</p></details><details><summary><b>5. 如何量化评估一个提示词的效果？评测集应该怎么构建？【进阶】</b></summary><p><strong>量化指标</strong>：① 任务成功率（输出通过 Schema 校验的比例）——最硬的指标，直接反映工程可用性；② 人工评分（抽样 + 双盲 1-5 分）；③ 用户满意度（👍👎 按钮埋点）；④ Token 成本（sum / 请求数）；⑤ 延迟 p50/p95/p99。</p><p><strong>评测集构建</strong>：① 50-200 条真实用户 query，覆盖正常 / 边界 / 异常（比如&quot;给我一个没有 bug 的 React 组件&quot; → 这是不存在的，看 LLM 会不会编造）；② 每条标注期望输出或评分标准；③ 新提示词跑同一评测集，对比指标变化；④ 成功率 ↓ 或成本 ↑ 显著时回滚。</p></details><details><summary><b>6. 一个 AI 代码审查应用，输出 JSON 包含 issues[] 和 summary，Schema 要求 issues[].severity 只能是 high|medium|low。LLM 第一轮输出 severity=&quot;critical&quot;（不在枚举内），第二轮修复了 severity 但 issues 是字符串不是数组。完整描述校验重试的代码逻辑。【挑战】</b></summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async function extractStructured(llm, schema, systemPrompt, userMsg, maxRetries=3):</span></span>
<span class="line"><span>  messages = [systemPrompt, userMsg]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  for attempt in 1..maxRetries:</span></span>
<span class="line"><span>    response = await llm.generate(messages)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Step 1: JSON.parse（捕获 issues 是字符串的格式错误）</span></span>
<span class="line"><span>    try: parsed = JSON.parse(response.json)</span></span>
<span class="line"><span>    catch err:</span></span>
<span class="line"><span>      messages += [assistant: response.json, user: &quot;不是合法 JSON，只输出 JSON&quot;]</span></span>
<span class="line"><span>      continue</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Step 2: Schema 校验（捕获 severity=&quot;critical&quot; 的枚举错误）</span></span>
<span class="line"><span>    result = schema.safeParse(parsed)</span></span>
<span class="line"><span>    if result.success: return { data: result.data, attempts: attempt }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Step 3: 错误喂回 LLM（第二轮就修 severity，第三轮彻底修好）</span></span>
<span class="line"><span>    messages += [</span></span>
<span class="line"><span>      assistant: response.json,</span></span>
<span class="line"><span>      user: \`校验错误：\${result.error.message}\\n请修复后重新输出 JSON\`</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  throw Error(&quot;超过最大重试次数&quot;)</span></span></code></pre></div><p>实际执行：第 1 轮 issues 是字符串 → JSON.parse 通过但 Schema 检查 issues 应该是 array → 喂回；第 2 轮 issues 是 array 了但 severity=&quot;critical&quot; 不在枚举内 → 喂回；第 3 轮 severity 修对、数组也对 → 通过，2 轮内收敛。关键：<strong>错误信息要精确到字段路径</strong>（<code>issues[0].severity: 必须是 high|medium|low 之一</code>），LLM 才能精确定位修复。</p></details><hr><h2 id="_104-7-本章避坑清单" tabindex="-1">104.7 本章避坑清单 <a class="header-anchor" href="#_104-7-本章避坑清单" aria-label="Permalink to &quot;104.7 本章避坑清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>坑点</th><th>现象</th><th>根因</th><th>正确姿势</th></tr></thead><tbody><tr><td>1</td><td>系统提示词太泛</td><td>LLM 输出质量忽高忽低，同一个问题两次答案风格完全不同</td><td>角色没锚定、没能力边界、没输出格式</td><td>四段落模板：Role / Capability / Constraints / Output Format</td></tr><tr><td>2</td><td>一次性塞全部需求</td><td>LLM 注意力稀释，后半部分约束经常被忽略</td><td>LLM 的有效注意力窗口有限</td><td>拆分多轮对话，每轮聚焦一个子任务；长提示词分段标记 <code># 段落名</code></td></tr><tr><td>3</td><td>结构化输出直接信任 LLM</td><td>前端 JSON.parse 报错、字段缺失、类型错误</td><td>LLM 只预测 token，不保证 schema 合规</td><td>必须加 JSON.parse + Schema 校验 + 校验失败自动重试（通常 3 轮收敛）</td></tr><tr><td>4</td><td>Few-shot 示例太多</td><td>token 预算浪费、成本翻 2-3 倍、效果反而下降</td><td>示例数量超过 5 个后，LLM 注意力被分散</td><td>3-5 个精心挑选的示例足够，覆盖关键场景即可</td></tr><tr><td>5</td><td>CoT 用在简单任务</td><td>输出变慢 2-3 倍、成本翻倍但质量没提升</td><td>直接查表/分类/格式化不需要推理</td><td>CoT 只用于复杂推理（数学、多步决策），简单任务直接要答案</td></tr><tr><td>6</td><td>CoT + 结构化输出混用</td><td>JSON 输出里夹杂推理文字，破坏 JSON 格式</td><td>推理过程和输出格式冲突</td><td>明确告诉 LLM：&quot;不要分析过程，直接输出 JSON&quot;</td></tr><tr><td>7</td><td>提示词不版本化</td><td>迭代后忘了改了什么、出问题无法回滚</td><td>没有版本管理机制</td><td>每个提示词带 <code>vX.Y.Z</code> 版本号 + 变更日志 + Git 管理</td></tr><tr><td>8</td><td>用主观感觉评判效果</td><td>&quot;新版本好像好一点？&quot; 但说不准哪里好</td><td>没有量化指标</td><td>用评测集跑新旧两个版本，对比成功率/成本/延迟三个硬指标</td></tr><tr><td>9</td><td>校验错误信息不精确</td><td>LLM 第二次还是输出同样的错误</td><td>只说 &quot;输出格式不对&quot;，没说具体哪里不对</td><td>把 Zod 的完整错误信息喂回：<code>issues[0].severity: 必须是 high|medium|low 之一</code></td></tr><tr><td>10</td><td>JSON Schema 用中文描述字段</td><td>某些 LLM 对中文 JSON 描述解析有偏差</td><td>LLM 训练数据主要是英文</td><td>Schema 描述用英文，业务提示词可以中文</td></tr><tr><td>11</td><td>Retry 次数无限循环</td><td>坏的 LLM API Key 或 schema 设计错了，重试几十次还是失败</td><td>没有上限保护</td><td>maxRetries=3 足够，超过就抛出错误告警（应该修提示词不是重试）</td></tr><tr><td>12</td><td>把用户输入直接拼进 system prompt</td><td>用户输入超长、污染人设、触发安全过滤</td><td>system prompt 应该稳定，用户输入单独放 user message</td><td>system prompt 永远固定，用户输入单独走 messages[-1]</td></tr><tr><td>13</td><td>用 Few-shot 替代 Constraints</td><td>示例里隐含了约束，但换个示例就漏了</td><td>隐式规则比显式规则脆弱</td><td>能用 Constraints 明确的就不用 Few-shot 隐含</td></tr><tr><td>14</td><td>评测集只 10 条 query</td><td>偶发问题测不出来、评分波动大</td><td>样本量太小</td><td>50-200 条真实用户 query，覆盖正常/边界/异常场景</td></tr><tr><td>15</td><td>提示词变更没做 A/B</td><td>改了系统提示词直接全量上线，质量可能暴跌</td><td>灰度和对比</td><td>新版本先灰度 5%，对比成功率/成本/延迟指标，至少 24 小时后再放量</td></tr><tr><td>16</td><td>不同模型共用同一套系统提示词</td><td>GPT-4o 效果很好，Claude 3.5 Sonnet 效果差</td><td>模型行为差异大，同一句提示词在不同模型上解释不同</td><td>系统提示词按模型分别调优，维护 prompt version × model 的二维矩阵</td></tr></tbody></table><blockquote><p>心法：<strong>提示词工程的本质是「约束 LLM 的自由度」</strong>——角色约束知识边界、Constraints 约束行为方式、Output Format 约束输出形态。你的约束越明确、越结构化，LLM 的表现越稳定。而稳定性的度量，永远靠<strong>量化指标 + A/B 对比</strong>，不是「我觉得好一点了」。</p></blockquote>`,74)])])}const g=a(p,[["render",i]]);export{u as __pageData,g as default};
